'use client';

import React, { useEffect, useRef, useState } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Protocol } from 'pmtiles';

// Register PMTiles protocol
const protocol = new Protocol();
maplibregl.addProtocol('pmtiles', protocol.tile);

export interface PMTilesMapProps {
  className?: string;
  onMapLoad?: (map: maplibregl.Map) => void;
  onMapError?: (error: Error) => void;
}

/**
 * PMTiles Map Component with proper layer configuration
 */
export default function NewPMTilesMap({ 
  className = '',
  onMapLoad,
  onMapError 
}: PMTilesMapProps) {
  const mapContainer = useRef<HTMLDivElement>(null);
  const map = useRef<maplibregl.Map | null>(null);
  const [status, setStatus] = useState<string>('Initializing...');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!mapContainer.current) return;

    try {
      setStatus('Creating map...');
      
      // Initialize map with dark background
      map.current = new maplibregl.Map({
        container: mapContainer.current,
        style: {
          version: 8,
          sources: {},
          layers: [
            {
              id: 'background',
              type: 'background',
              paint: {
                'background-color': '#1a1a1a'
              }
            }
          ]
        },
        center: [10.0, 56.0], // Denmark center
        zoom: 6,
        maxZoom: 15,
        minZoom: 4
      });

      map.current.on('load', () => {
        setStatus('Map loaded, adding data sources...');
        
        if (map.current) {
          setStatus('Adding kommune data...');

          // Add kommune data source
          map.current.addSource('kommune-data', {
            type: 'vector',
            url: 'pmtiles://http://localhost:3000/api/pmtiles/kommune_pfas_2023.pmtiles'
          });

          // Try to add kommune layer with proper styling
          try {
            map.current.addLayer({
              id: 'kommune-layer',
              source: 'kommune-data',
              'source-layer': 'kommune_pfas_2023', // Most likely source layer name
              type: 'fill',
              paint: {
                'fill-color': [
                  'interpolate',
                  ['linear'],
                  ['get', 'pesticide_belastning_per_ha'],
                  0, 'rgba(255,255,255,0)',
                  1, '#ffeeee',
                  10, '#ffcccc',
                  50, '#ff9999',
                  100, '#ff6666',
                  500, '#ff3333',
                  1000, '#ff0000'
                ],
                'fill-opacity': 0.8
              }
            });

            // Add kommune borders
            map.current.addLayer({
              id: 'kommune-borders',
              source: 'kommune-data',
              'source-layer': 'kommune_pfas_2023',
              type: 'line',
              paint: {
                'line-color': '#ffffff',
                'line-width': 1,
                'line-opacity': 0.5
              }
            });

            setStatus('Kommune layer added successfully');
          } catch (e) {
            console.log('Failed to add kommune layer with default source-layer, trying alternatives...', e);
            
            // Try alternative source layer names
            const alternativeNames = ['default', 'kommune', 'data', 'layer0'];
            for (const sourceLayer of alternativeNames) {
              try {
                map.current.addLayer({
                  id: `kommune-layer-${sourceLayer}`,
                  source: 'kommune-data',
                  'source-layer': sourceLayer,
                  type: 'fill',
                  paint: {
                    'fill-color': [
                      'interpolate',
                      ['linear'],
                      ['get', 'pesticide_belastning_per_ha'],
                      0, 'rgba(255,255,255,0)',
                      1, '#ffeeee',
                      10, '#ffcccc',
                      50, '#ff9999',
                      100, '#ff6666',
                      500, '#ff3333',
                      1000, '#ff0000'
                    ],
                    'fill-opacity': 0.8
                  }
                });
                
                setStatus(`Kommune layer added with source-layer: ${sourceLayer}`);
                break;
              } catch (err) {
                console.log(`Failed with source-layer: ${sourceLayer}`, err);
              }
            }
          }

          setStatus('Adding H3 data...');

          // Add H3 data source
          map.current.addSource('h3-data', {
            type: 'vector',
            url: 'pmtiles://http://localhost:3000/api/pmtiles/h3_pfas_2023_res8.pmtiles'
          });

          // Add H3 layer
          try {
            map.current.addLayer({
              id: 'h3-layer',
              source: 'h3-data',
              'source-layer': 'h3_pfas_2023_res8',
              type: 'fill',
              paint: {
                'fill-color': [
                  'interpolate',
                  ['linear'],
                  ['get', 'pesticide_belastning_per_ha'],
                  0, 'rgba(255,255,255,0)',
                  1, '#ffeeee',
                  10, '#ffcccc',
                  50, '#ff9999',
                  100, '#ff6666',
                  500, '#ff3333',
                  1000, '#ff0000'
                ],
                'fill-opacity': 0.7
              },
              layout: {
                visibility: 'none' // Start hidden, show at high zoom
              }
            });

            setStatus('H3 layer added successfully');
          } catch (e) {
            console.log('Failed to add H3 layer, trying alternatives...', e);
            
            const h3AlternativeNames = ['default', 'h3', 'data', 'layer0'];
            for (const sourceLayer of h3AlternativeNames) {
              try {
                map.current.addLayer({
                  id: `h3-layer-${sourceLayer}`,
                  source: 'h3-data',
                  'source-layer': sourceLayer,
                  type: 'fill',
                  paint: {
                    'fill-color': [
                      'interpolate',
                      ['linear'],
                      ['get', 'pesticide_belastning_per_ha'],
                      0, 'rgba(255,255,255,0)',
                      1, '#ffeeee',
                      10, '#ffcccc',
                      50, '#ff9999',
                      100, '#ff6666',
                      500, '#ff3333',
                      1000, '#ff0000'
                    ],
                    'fill-opacity': 0.7
                  },
                  layout: {
                    visibility: 'none'
                  }
                });
                
                setStatus(`H3 layer added with source-layer: ${sourceLayer}`);
                break;
              } catch (err) {
                console.log(`Failed H3 with source-layer: ${sourceLayer}`, err);
              }
            }
          }

          // Add zoom-based layer switching
          map.current.on('zoom', () => {
            if (map.current) {
              const zoom = map.current.getZoom();
              
              // Show kommune at low zoom, H3 at high zoom
              if (zoom < 9) {
                // Show kommune layers
                const kommuneLayers = map.current.getStyle().layers.filter(l => l.id.startsWith('kommune-'));
                kommuneLayers.forEach(layer => {
                  map.current!.setLayoutProperty(layer.id, 'visibility', 'visible');
                });
                
                // Hide H3 layers
                const h3Layers = map.current.getStyle().layers.filter(l => l.id.startsWith('h3-'));
                h3Layers.forEach(layer => {
                  map.current!.setLayoutProperty(layer.id, 'visibility', 'none');
                });
              } else {
                // Hide kommune layers
                const kommuneLayers = map.current.getStyle().layers.filter(l => l.id.startsWith('kommune-'));
                kommuneLayers.forEach(layer => {
                  map.current!.setLayoutProperty(layer.id, 'visibility', 'none');
                });
                
                // Show H3 layers
                const h3Layers = map.current.getStyle().layers.filter(l => l.id.startsWith('h3-'));
                h3Layers.forEach(layer => {
                  map.current!.setLayoutProperty(layer.id, 'visibility', 'visible');
                });
              }
            }
          });

          // Add navigation controls
          map.current.addControl(new maplibregl.NavigationControl(), 'top-right');

          setStatus('Map setup complete!');
          onMapLoad?.(map.current);
        }
      });

      map.current.on('error', (e) => {
        console.error('Map error:', e);
        const errorMsg = e.error?.message || 'Unknown map error';
        setError(errorMsg);
        onMapError?.(new Error(errorMsg));
      });

      map.current.on('sourcedata', (e) => {
        if (e.isSourceLoaded) {
          console.log(`Source loaded: ${e.sourceId}`);
          setStatus(`Source loaded: ${e.sourceId}`);
        }
      });

    } catch (e) {
      const errorMsg = e instanceof Error ? e.message : 'Failed to initialize map';
      console.error('Map initialization error:', e);
      setError(errorMsg);
      onMapError?.(new Error(errorMsg));
    }

    // Cleanup
    return () => {
      if (map.current) {
        map.current.remove();
        map.current = null;
      }
    };
  }, [onMapLoad, onMapError]);

  if (error) {
    return (
      <div className={`${className} bg-black flex items-center justify-center`}>
        <div className="text-center text-white">
          <div className="text-red-400 text-sm mb-2">Error: {error}</div>
          <button
            onClick={() => window.location.reload()}
            className="px-3 py-1 bg-white text-black text-sm rounded hover:bg-gray-100 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`${className} relative`}>
      <div ref={mapContainer} className="w-full h-full" />
      <div className="absolute top-4 left-4 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded">
        Status: {status}
      </div>
    </div>
  );
} 